     "text": "許多少數族裔人士的母語都並非中文，但在香港，大部分日常生活和工作環境都以中文作為主要語言，令他們無論在學業或工作上都會遇到許多問題。在2017年，超過一千名報考香港中學文憑考試的非華語學生中，只有約一百名考中國語文科，其中不足三成考生的成績符合受資助大學的入學要求，遠遠低於香港全體考生的56%。少數族裔人士難以在香港學好中文有幾個原因，其中一個是因為他們的母語語法和語言特點都與中文有很大差異，令他們難以在課堂中學習中文。而且，他們通常與其他少數族裔人士聚居在一起，日常生活中缺少使用中文的機會，令他們更難掌握用中文與他人溝通的技巧。"
