     "type": "open",
     "q": "根據資料A，說明網上購物平台吸引消費者消費的兩種方法。",
     "model": "首先，網購平台會按消費者喜好推薦商品。根據資料A，《大公報》調查顯示網購平台會利用人工智能分析消費者的購物記錄，從而推薦商品，以吸引消費。而其中九成的受訪者曾因為產品推薦而作出非理性消費。可見電子購物平台利用人工智能推薦符合消費者喜好的商品，以吸引消費者購物。（2分）\n其次，網購平台會提供折扣商品吸引消費者購買。根據資料A，有受訪者表示因網上平台折扣商品而消費，更曾因而額外買入2000元的化妝品。可見，網上購物平台利用折扣吸引消費者購物。（2分）",
