     "text": "香港正申請加入現時全球規模最大的自由貿易協定《區域全面經濟伙伴關係協定》（RCEP）。有官員透露，國家正敦促各成員國盡快完成審核新成員申請，預期香港可於今年內加入。他重申，所有RCEP成員均是香港重要貿易伙伴，佔香港商品貿易總額約70%和服務貿易總額約40%，認為香港具備充分條件加入RCEP，並憑藉香港作為物流、貿易和金融中心的優勢，進一步優化區域供應鏈，為RCEP貢獻獨特價值。"
