     "text": "華　生：「張姑娘，我失戀呀……好難過。」\n張姑娘：「你可以說給我聽聽，讓我與你分擔煩惱。」\n華　生：「小敏對我越來越冷淡，最近兩個月我們已經很少見面。上星期日是我們拍拖一周年紀念日，她約我去附近商場的餐廳吃飯。當時我很高興，以為她約我慶祝。」\n張姑娘：「後來怎樣？」\n華　生：「我特地準備好禮物，提早到餐廳等候……誰知道……」\n張姑娘：「小敏向你提出分手？」\n華　生：「是。她決絕地向我講分手……我早就懷疑小敏喜歡上別人，移情別戀……」\n張姑娘：「小敏承認這是與你分手的原因嗎？」\n華　生：「她指責我沒有做好男朋友的本分，罵我對她不夠好，因此才變心……」\n張姑娘：「……」"
